"""The UGS benchmark: scenarios generated by the reference simulator, a tank baseline, and the metrics.

The benchmark of the programme (#1085) asks for a scenario dataset, several surrogates trained at an equal
budget, and a speed-up that counts data generation and training. What this module delivers is the part that
does not depend on a surrogate existing: the synthetic model, the scenario dataset generated by the reference
simulator, a **tank (material balance) baseline**, the *ruler* -- relative L2 and R-squared of the pressure
field, bottom-hole-pressure error at the wells, deliverability error per day, inference time per scenario and
the break-even number of evaluations -- and the conservation check a predicted field has to pass.

**The neural surrogate is not here.** The neural-operator work is #1084 (three-dimensional and space-time FNO,
factorised spectral weights, Sobolev H1 loss) and this pass did not do it, so
:func:`run_benchmark` reports ``surrogate: {"present": False}`` with the reason rather than a number it does
not have. What the surrogate has to beat is measured and reported.

The synthetic model
-------------------
A 25 x 25 areal grid of 40 m cells (1000 m across), 10 m thick, with a log-normal permeability field of
correlation length 200 m and a porosity field correlated with it; nine wells on a 3 x 3 pattern. Scenarios are
a season -- injection at a bottom-hole pressure, a shut-in, withdrawal at a bottom-hole pressure -- sampled by
Latin hypercube over the pressure levels, a spatial gradient of the withdrawal pressure, the number of wells
shut in and the two durations. The ``extrapolation`` split holds the cases a surrogate must not be trusted on:
withdrawal pressures below the training range (the rates beyond it) and wells shut that were always open.

The tank baseline
-----------------
Zero-dimensional, and the first thing a reservoir engineer computes: the average pressure from the material
balance, ``GIP(p) = GIP(p_0) - produced``, with each well's rate from Peaceman's inflow against that average
pressure, ``q = WI (1/Bg)/mu (p_bhp - p)``. It has no spatial structure and no interference between wells,
which is exactly what the metrics then measure.
"""
from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import Any

import numpy as np

from .grid import CartesianGrid, gaussian_field
from .pvt import Gas, Rock
from .simulator import SimConfig, UGSSimulator
from .wells import Control, Period, Schedule, Well

__all__ = [
    "UGSModel", "synthetic_model", "Scenario", "ScenarioDataset", "default_scenarios",
    "simulate_scenarios", "generate_dataset", "TankBaseline", "metrics", "run_benchmark",
]

DAYS = 86400.0


@dataclass
class UGSModel:
    """Everything the simulator needs, in one object the scenarios and the baseline share."""

    grid: CartesianGrid
    fluid: Gas
    rock: Rock
    wells: list[Well]
    p0: float
    name: str = "synthetic"

    def simulator(self) -> UGSSimulator:
        return UGSSimulator(self.grid, self.fluid, self.rock, self.wells, p0=self.p0)


def synthetic_model(*, seed: int = 0, shape=(25, 25), spacing: float = 40.0, thickness: float = 10.0,
                    mean_permeability: float = 2.0e-14, sigma: float = 0.5, corr_length: float = 200.0,
                    p0: float = 1.2e7, T: float = 320.0) -> UGSModel:
    """The synthetic UGS model the benchmark runs on: an anticline-flat areal grid with nine wells."""
    permeability = mean_permeability * gaussian_field(shape, (spacing,), corr_length, sigma, seed)
    porosity = np.clip(0.20 * gaussian_field(shape, (spacing,), corr_length, 0.25, seed + 101), 0.08, 0.32)
    grid = CartesianGrid(shape, (spacing, spacing), permeability=permeability, porosity=porosity)
    wells = []
    nx, ny = shape
    for j, jy in enumerate((2, ny // 2, ny - 3)):
        for i, ix in enumerate((2, nx // 2, nx - 3)):
            cell = int(np.ravel_multi_index((ix, jy), shape))
            wells.append(Well(f"P{i + 1}-{j + 1}", cell, r_w=0.1, bhp_min=3.0e6, bhp_max=2.8e7,
                              rate_max=1.2))
    return UGSModel(grid=grid, fluid=Gas(T=T), rock=Rock(cr=2.0e-9, p_ref=p0), wells=wells, p0=p0)


@dataclass(frozen=True)
class Scenario:
    """One season: a schedule, the split it belongs to, and why it is where it is."""

    name: str
    split: str
    schedule: Schedule
    note: str = ""


@dataclass
class ScenarioDataset:
    """Scenarios and what the reference simulator returned for each of them."""

    scenarios: list[Scenario]
    times_days: np.ndarray                # (n_t,)
    pressure: np.ndarray                  # (n_scen, n_t, n_cells) [Pa]
    well_rate: dict[str, np.ndarray]      # name -> (n_scen, n_t) [m3/d]
    well_bhp: dict[str, np.ndarray]       # name -> (n_scen, n_t) [Pa]
    model: UGSModel
    mass_balance_error: float
    simulator_seconds: float
    converged: list[bool] = field(default_factory=list)

    @property
    def n_scenarios(self) -> int:
        return len(self.scenarios)

    def indices(self, split: str) -> list[int]:
        return [i for i, s in enumerate(self.scenarios) if s.split == split]

    def splits(self) -> list[str]:
        seen: list[str] = []
        for s in self.scenarios:
            if s.split not in seen:
                seen.append(s.split)
        return seen

    def save(self, path) -> None:
        np.savez_compressed(
            path,
            names=np.array([s.name for s in self.scenarios]),
            splits=np.array([s.split for s in self.scenarios]),
            times_days=self.times_days,
            pressure=self.pressure,
            mass_balance_error=np.array(self.mass_balance_error),
            simulator_seconds=np.array(self.simulator_seconds),
            **{f"rate_{k}": v for k, v in self.well_rate.items()},
            **{f"bhp_{k}": v for k, v in self.well_bhp.items()},
        )
        # the schedules are data, not arrays: they go next to the arrays as an npz of their descriptor
        import json
        from pathlib import Path
        descriptor = {
            "model": self.model.name,
            "scenarios": [
                {"name": s.name, "split": s.split, "note": s.note,
                 "periods": [{"days": p.days, "label": p.label,
                              "controls": {k: [c.mode, c.value] for k, c in p.controls.items()}}
                             for p in s.schedule.periods]}
                for s in self.scenarios
            ],
        }
        Path(path).with_suffix(".json").write_text(json.dumps(descriptor, indent=1), encoding="utf-8")


def _controls(model: UGSModel, withdrawal_bhp, injection_bhp, gradient: float, shut: set[str],
              days_inj: float, days_wd: float) -> Schedule:
    """Build the season: injection, a two-day shut-in, then withdrawal."""
    wells = model.wells
    xs = np.array([np.unravel_index(w.cell, model.grid.shape)[0] for w in wells], dtype=float)
    xs = (xs - xs.mean()) / max(xs.max() - xs.mean(), 1.0)     # -1 .. 1 across the field
    inject = {w.name: Control("bhp", injection_bhp) for w in wells if w.name not in shut}
    withdraw = {w.name: Control("bhp", max(withdrawal_bhp + gradient * x, 4.0e6))
                for w, x in zip(wells, xs, strict=True) if w.name not in shut}
    return Schedule((
        Period(days_inj, inject, "injection"),
        Period(2.0, {}, "shut-in"),
        Period(days_wd, withdraw, "withdrawal"),
    ))


DAYS_INJECTION = 13.0
DAYS_SHUT_IN = 2.0
DAYS_WITHDRAWAL = 10.0


def default_scenarios(model: UGSModel, *, n: int = 12, seed: int = 0) -> list[Scenario]:
    """Latin-hypercube scenarios over four season parameters, plus three extrapolation cases.

    The sampled parameters are the injection bottom-hole pressure, the withdrawal bottom-hole pressure, a
    spatial gradient of the withdrawal pressure across the field, and the number of wells shut in for the
    season. The three period durations are fixed (:data:`DAYS_INJECTION`, :data:`DAYS_SHUT_IN`,
    :data:`DAYS_WITHDRAWAL`) so that every scenario shares one time axis, which is what a surrogate dataset
    needs; they stay parameters of the simulator and of the deliverability optimiser. Each scenario is named
    ``S00``.. and split 60 / 20 / 20 into train, validation and test by its position.
    """
    from scipy.stats import qmc

    sampler = qmc.LatinHypercube(d=4, seed=seed)
    unit = sampler.random(n)
    names = [w.name for w in model.wells]
    n_train = max(1, int(round(0.6 * n)))          # a split that still has a training case at small n
    n_validation = int(round(0.2 * n))
    scenarios: list[Scenario] = []
    for i, u in enumerate(unit):
        injection_bhp = 1.8e7 + 0.6e7 * u[0]          # 18 .. 24 MPa
        withdrawal_bhp = 6.0e6 + 4.0e6 * u[1]         # 6 .. 10 MPa
        gradient = -2.0e6 + 4.0e6 * u[2]              # -2 .. +2 MPa across the field
        n_shut = int(np.floor(u[3] * 4.0))            # 0 .. 3 wells closed for the season
        days_inj, days_wd = DAYS_INJECTION, DAYS_WITHDRAWAL
        shut = set(names[:n_shut])
        split = "train" if i < n_train else ("validation" if i < n_train + n_validation else "test")
        scenarios.append(Scenario(
            f"S{i:02d}", split,
            _controls(model, withdrawal_bhp, injection_bhp, gradient, shut, days_inj, days_wd),
            f"bhp_inj {injection_bhp / 1e6:.1f} MPa, bhp_wd {withdrawal_bhp / 1e6:.1f} MPa, "
            f"gradient {gradient / 1e6:+.1f} MPa, {n_shut} shut",
        ))
    scenarios.append(Scenario(
        "X0", "extrapolation",
        _controls(model, 3.0e6, 2.2e7, 0.0, set(), DAYS_INJECTION, DAYS_WITHDRAWAL),
        "withdrawal pressure 3.0 MPa, below the training range: rates beyond it"))
    scenarios.append(Scenario(
        "X1", "extrapolation",
        _controls(model, 7.0e6, 2.0e7, 0.0, set(), DAYS_INJECTION, DAYS_WITHDRAWAL),
        "every well open, the case the training set always has some of them shut in"))
    scenarios.append(Scenario(
        "X2", "extrapolation",
        _controls(model, 5.0e6, 2.4e7, 3.0e6, {names[0], names[-1]}, DAYS_INJECTION, DAYS_WITHDRAWAL),
        "a 3 MPa gradient with two wells shut: both out of the sampled envelope"))
    return scenarios


def simulate_scenarios(model: UGSModel, scenarios: list[Scenario],
                       config: SimConfig | None = None) -> ScenarioDataset:
    """Run every scenario on the reference simulator, recording the fields and the wells."""
    config = config or SimConfig(dt_days=1.0)
    sim = model.simulator()
    times = None
    pressure = []
    rates: dict[str, list] = {w.name: [] for w in model.wells}
    bhps: dict[str, list] = {w.name: [] for w in model.wells}
    converged = []
    worst_balance = 0.0
    t0 = time.perf_counter()
    for scenario in scenarios:
        result = sim.run(scenario.schedule, config)
        converged.append(result.converged)
        worst_balance = max(worst_balance, abs(result.mass_balance_error))
        if times is None:
            times = result.times_days
            n_t = len(times)
        if len(result.times_days) != len(times):
            raise RuntimeError(f"scenario {scenario.name} ran {len(result.times_days)} steps and the first "
                               f"ran {len(times)}: the dataset needs one time axis")
        fields = result.pressure
        if fields.shape[0] < n_t:                     # a run that stopped early, padded with its last field
            fields = np.vstack([fields, np.repeat(fields[-1:], n_t - fields.shape[0], axis=0)])
        pressure.append(fields[:n_t])
        for name in rates:
            r = result.well_rate[name]
            b = result.well_bhp[name]
            rates[name].append(np.pad(r, (0, n_t - len(r)), mode="edge") if len(r) < n_t else r[:n_t])
            bhps[name].append(np.pad(b, (0, n_t - len(b)), mode="edge") if len(b) < n_t else b[:n_t])
    seconds = time.perf_counter() - t0
    return ScenarioDataset(
        scenarios=list(scenarios),
        times_days=np.asarray(times, dtype=float),
        pressure=np.array(pressure),
        well_rate={k: np.array(v) for k, v in rates.items()},
        well_bhp={k: np.array(v) for k, v in bhps.items()},
        model=model,
        mass_balance_error=float(worst_balance),
        simulator_seconds=float(seconds),
        converged=converged,
    )


def generate_dataset(*, n_scenarios: int = 12, seed: int = 0, dt_days: float = 1.0,
                     model: UGSModel | None = None) -> ScenarioDataset:
    """The benchmark's data-generation step: build the model, sample the scenarios, run the simulator."""
    model = model or synthetic_model(seed=seed)
    scenarios = default_scenarios(model, n=n_scenarios, seed=seed)
    return simulate_scenarios(model, scenarios, SimConfig(dt_days=dt_days))


class TankBaseline:
    """The zero-dimensional material-balance model: one average pressure, Peaceman inflow per well.

    At every step each well's rate is ``q = WI (1/Bg)/mu (p_bhp - p_average)`` (or the scheduled rate, for a
    well on rate control), clipped by the well's limits, and the average pressure follows from the material
    balance ``GIP(p) = GIP(p_previous) - produced``. The predicted pressure field is that average, everywhere:
    the model has no spatial structure, which is what the field metrics measure. Because the pressure follows
    from the gas in place, the prediction conserves mass by construction -- and that is checked, not assumed.
    """

    def __init__(self, model: UGSModel):
        self.model = model
        self.sim = model.simulator()

    def predict(self, dataset: ScenarioDataset) -> dict[str, Any]:
        """Predict every scenario. Returns the pressure ``(n_scen, n_t, n_cells)`` and the well histories."""
        model, sim = self.model, self.sim
        times = dataset.times_days
        n_scen, n_t = dataset.pressure.shape[0], len(times)
        pressure = np.zeros((n_scen, n_t, model.grid.n_cells))
        rates = {w.name: np.zeros((n_scen, n_t)) for w in model.wells}
        bhps = {w.name: np.zeros((n_scen, n_t)) for w in model.wells}
        gip0 = sim.gas_in_place_uniform(model.p0)
        worst = 0.0
        for s, scenario in enumerate(dataset.scenarios):
            gip = gip0
            p = model.p0
            pressure[s, 0] = p
            for w in model.wells:
                bhps[w.name][s, 0] = p
            for step in range(1, n_t):
                dt = (times[step] - times[step - 1]) * DAYS
                controls = scenario.schedule.controls_at(times[step] - 1e-9)
                moved = 0.0
                for w in model.wells:
                    ctrl = controls.get(w.name)
                    q = self._rate(w, ctrl, p)
                    rates[w.name][s, step] = q * DAYS
                    bhps[w.name][s, step] = self._bhp(w, ctrl, q, p)
                    moved += q * dt
                gip += moved
                p = sim.pressure_for_gas_in_place(gip, guess=p)
                pressure[s, step] = p
            moved_total = float(np.sum([np.sum(rates[k][s, 1:] * np.diff(times)) for k in rates]))
            worst = max(worst, abs(gip - gip0 - moved_total) / gip0)
        return {"pressure": pressure, "well_rate": rates, "well_bhp": bhps, "mass_balance_error": float(worst)}

    def _mobility(self, p: float) -> float:
        fluid = self.model.fluid
        return float(fluid.index(p) / fluid.mu(p))

    def _rate(self, well: Well, ctrl: Control | None, p: float) -> float:
        from .wells import operating_point
        q, _bhp, _dq = operating_point(well, ctrl, p, self._mobility(p), 0.0, self.sim.wi[well.name])
        return q

    def _bhp(self, well: Well, ctrl: Control | None, q: float, p: float) -> float:
        return float(p + q / (self.sim.wi[well.name] * self._mobility(p)))


def metrics(dataset: ScenarioDataset, prediction: dict[str, Any], *, split: str | None = None) -> dict[str, Any]:
    """The ruler: field error, R-squared, well errors and deliverability error, per split and overall."""
    idx = list(range(dataset.n_scenarios)) if split is None else dataset.indices(split)
    if not idx:
        return {"ok": False, "reason": f"no scenario in the split {split!r}"}
    model = dataset.model
    pred = prediction["pressure"][idx]
    true = dataset.pressure[idx]
    err = pred - true
    p0 = np.full_like(true, model.p0)
    out: dict[str, Any] = {
        "ok": True,
        "split": split or "all",
        "n_scenarios": len(idx),
        "relative_l2": float(np.linalg.norm(err) / np.linalg.norm(true)),
        "relative_l2_change": float(np.linalg.norm(err) / np.linalg.norm(true - p0)),
        "r2": float(1.0 - np.sum(err ** 2) / np.sum((true - true.mean()) ** 2)),
        "max_abs_pressure_error": float(np.max(np.abs(err))),
    }
    # the well errors are quoted against one scale for the whole split -- the largest pressure or rate
    # excursion any well makes -- because a per-well scale divides by the change of a well that barely moved
    bhp_abs = {w.name: float(np.max(np.abs(prediction["well_bhp"][w.name][idx]
                                             - dataset.well_bhp[w.name][idx]))) for w in model.wells}
    bhp_scale = max(float(np.max(np.ptp(dataset.well_bhp[w.name][idx], axis=1))) for w in model.wells)
    rate_scale = max(float(np.max(np.abs(dataset.well_rate[w.name][idx]))) for w in model.wells)
    true_total = -np.sum([dataset.well_rate[w.name][idx] for w in model.wells], axis=0)
    pred_total = -np.sum([prediction["well_rate"][w.name][idx] for w in model.wells], axis=0)
    out["bhp_error_MPa"] = float(max(bhp_abs.values()) / 1e6)
    out["bhp_error"] = float(max(bhp_abs.values()) / max(bhp_scale, 1e-12))
    out["deliverability_error"] = float(np.max(np.abs(pred_total - true_total))
                                        / max(rate_scale * len(model.wells), 1e-12))
    return out


def run_benchmark(*, n_scenarios: int = 12, seed: int = 0, dt_days: float = 1.0) -> dict[str, Any]:
    """Generate the dataset, run the tank baseline and report the ruler -- and the surrogate that is missing."""
    dataset = generate_dataset(n_scenarios=n_scenarios, seed=seed, dt_days=dt_days)
    baseline = TankBaseline(dataset.model)
    t0 = time.perf_counter()
    prediction = baseline.predict(dataset)
    baseline_seconds = time.perf_counter() - t0
    per_scenario = dataset.simulator_seconds / dataset.n_scenarios
    report: dict[str, Any] = {
        "dataset": {
            "model": dataset.model.name,
            "scenarios": dataset.n_scenarios,
            "splits": {name: len(dataset.indices(name)) for name in dataset.splits()},
            "cells": dataset.model.grid.n_cells,
            "wells": len(dataset.model.wells),
            "steps": len(dataset.times_days) - 1,
            "all_converged": bool(all(dataset.converged)),
            "mass_balance_error": dataset.mass_balance_error,
            "simulator_seconds": dataset.simulator_seconds,
            "simulator_seconds_per_scenario": per_scenario,
        },
        "baseline": {
            "name": "tank (material balance) + Peaceman inflow",
            "seconds_per_scenario": baseline_seconds / dataset.n_scenarios,
            "mass_balance_error": prediction["mass_balance_error"],
            "metrics": {name: metrics(dataset, prediction, split=name) for name in dataset.splits()},
        },
        "surrogate": {
            "present": False,
            "reason": "the neural operator of #1084 (3-D / space-time FNO with factorised spectral weights and "
                      "a Sobolev H1 loss) is not in this pass, so there is no trained surrogate, no inference "
                      "time and no speed-up to report; the dataset and the ruler it has to beat are here",
        },
        "speedup": {
            "simulator_seconds_per_scenario": per_scenario,
            "baseline_seconds_per_scenario": baseline_seconds / dataset.n_scenarios,
            "break_even_evaluations": None,
            "reason": "a break-even needs a surrogate's inference time and its training cost; neither exists "
                      "yet, so the number is not quoted",
        },
    }
    report["baseline"]["metrics"]["all"] = metrics(dataset, prediction)
    return report
